// cSC4RenderProperties — the renderer's tunable switches (28 functions plus the 77 cRegk* registration
// constructors, 0x10028c8ce..0x10028d9ca and 0x10028db18..): 38 boolean, 24 integer and 15 float properties, each
// with a registry key name, a shortcut and (for numbers) default / minimum / maximum. The registration order of the
// cRegk constructors (cProperties::cProperties) is the property index; the table lives in
// RenderPropertyDefaults.inc (generated by scripts/gen_renderprops.py from the constructors).
// Each instance copies the table and normalises the names: the leading 'k' is dropped, the shortcut is the
// lower-cased capitals of that name, and the name itself is lower-cased.
#pragma once
#include <cctype>
#include <cstdint>
#include <string>
#include <vector>

#include "rz/cRZUnknown.h"

namespace sc4 {

template <class T>
struct cSC4RenderProperty {
    std::int32_t id = 0;          // +0
    std::string name;             // +8
    std::string shortcut;         // +0x20
    T value{};                    // +0x38
    T minimum{};                  // +0x3c
    T maximum{};                  // +0x40
};
template <>
struct cSC4RenderProperty<bool> {
    std::int32_t id = 0;
    std::string name;
    std::string shortcut;
    bool value = false;           // +0x38
    bool flag39 = false;          // +0x39
    bool flag3a = false;          // +0x3a
};

// The registry (static in the original; filled by the cRegk* constructors).
struct RenderPropertyRegistry {
    std::vector<cSC4RenderProperty<bool>> bools;
    std::vector<cSC4RenderProperty<std::int32_t>> ints;
    std::vector<cSC4RenderProperty<float>> floats;
};
const RenderPropertyRegistry& DefaultRenderProperties();   // built on first use from the generated table

class cSC4RenderProperties : public cRZUnknown {
public:
    cSC4RenderProperties();

    std::uint32_t NumBoolProperties() const { return static_cast<std::uint32_t>(bools_.size()); }
    std::int32_t NumIntProperties() const { return static_cast<std::int32_t>(ints_.size()); }
    std::int32_t NumFloatProperties() const { return static_cast<std::int32_t>(floats_.size()); }
    bool BoolValue(std::uint32_t index) const { return bools_[index].value; }
    std::int32_t IntValue(std::uint32_t index) const { return ints_[index].value; }
    float FloatValue(std::uint32_t index) const { return floats_[index].value; }
    void SetBoolValue(std::uint32_t index, bool value) { bools_[index].value = value; }
    void SetIntValue(std::uint32_t index, std::int32_t value) { ints_[index].value = value; }
    void SetFloatValue(std::uint32_t index, float value) { floats_[index].value = value; }
    // index of the property whose (lower-cased) name or shortcut matches, 0xffffffff when none does
    std::uint32_t BoolPropertyIDFromName(const char* name) const { return Find(bools_, name); }
    std::uint32_t IntPropertyIDFromName(const char* name) const { return Find(ints_, name); }
    std::uint32_t FloatPropertyIDFromName(const char* name) const { return Find(floats_, name); }
    const char* NameFromBoolPropertyID(std::uint32_t index) const { return bools_[index].name.c_str(); }
    const char* NameFromIntPropertyID(std::uint32_t index) const { return ints_[index].name.c_str(); }
    const char* NameFromFloatPropertyID(std::uint32_t index) const { return floats_[index].name.c_str(); }

    static std::string MakeShortcut(const std::string& name);   // lower-cased capital letters of `name`

private:
    template <class V>
    static std::uint32_t Find(const std::vector<V>& list, const char* name);
    template <class V>
    static void Normalise(std::vector<V>& list);

    std::vector<cSC4RenderProperty<bool>> bools_;                 // +0x18
    std::vector<cSC4RenderProperty<std::int32_t>> ints_;          // +0x30
    std::vector<cSC4RenderProperty<float>> floats_;               // +0x48
};

template <class V>
std::uint32_t cSC4RenderProperties::Find(const std::vector<V>& list, const char* name) {
    std::string lower(name);
    for (char& c : lower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    for (std::size_t i = 0; i < list.size(); ++i)
        if (list[i].name == lower || list[i].shortcut == lower) return static_cast<std::uint32_t>(i);
    return 0xffffffffu;
}

}  // namespace sc4
